COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(100,('Puppy scam checks before you send money','Verify the seller and the animal independently before paying. A convincing website, photograph or club logo is a claim to check—not proof that a puppy or legitimate organization exists.'),('Comprueba posibles estafas antes de pagar','Verifica vendedor y animal de forma independiente. Web, foto o logotipo convincente son afirmaciones por comprobar, no prueba de que exista el cachorro o una organización legítima.'),[
('Start outside the seller’s links','Search the seller or business name with terms such as scam, complaint and review. Compare contact details using independently found organization websites. Look for copied puppy images with an image search. A clean search result is not a guarantee: a new impersonation may have no complaint history.'),('Check identity and the actual animal','Ask how you can meet or observe the actual puppy and caregiver through a safe, verifiable arrangement. Confirm claimed club membership with the club using its official contact details. A copied registration document, prerecorded video or social profile can be impersonated; avoid relying on a single item of evidence.'),('Pause when payment pressure appears','Be cautious about urgent deposits, payment through gift cards, cryptocurrency or methods with limited recovery options, and unexpected transport or insurance charges. Verify a claimed carrier directly through its official website. Do not send additional money just because a previous payment has already been made.'),('A worked warning-sign example','Illustrative example: a seller refuses independent identity checks, insists on immediate payment and later introduces a separate shipping fee from a new contact. Pause the transaction, save the messages and verify the claims independently. These warning signs justify caution but are not a legal finding about a named person.'),('If you suspect you have been scammed','Contact your payment provider promptly using its official channel and ask what reporting or dispute options apply. Preserve receipts, messages and the listing address. In the United States, report suspected fraud at ReportFraud.ftc.gov; elsewhere use the appropriate local reporting authority. Reporting does not guarantee recovery, and offers to recover money for an advance fee deserve independent verification.')],[
('Empieza fuera de sus enlaces','Busca nombre con estafa, queja y reseña. Compara datos con webs oficiales encontradas por separado y busca posibles fotos copiadas. No encontrar quejas no garantiza legitimidad; una suplantación nueva puede no tener historial.'),('Verifica identidad y animal','Pregunta cómo observar al cachorro y cuidador mediante un encuentro seguro y verificable. Confirma pertenencia a clubes por contacto oficial. Documento, vídeo grabado o perfil pueden suplantarse; no dependas de una sola prueba.'),('Para ante presión de pago','Desconfía de depósitos urgentes, tarjetas regalo, criptomonedas, métodos con recuperación limitada y cargos inesperados de transporte o seguro. Verifica transportista por su web oficial. No envíes más dinero solo por haber pagado antes.'),('Ejemplo de señales','Ejemplo ilustrativo: rechaza comprobar identidad, exige pago inmediato y añade una tarifa de envío desde otro contacto. Pausa, conserva mensajes y verifica por separado. Son motivos de cautela, no una conclusión legal sobre alguien identificado.'),('Si sospechas estafa','Contacta pronto con el proveedor de pago por su canal oficial para consultar opciones. Conserva recibos, mensajes y dirección del anuncio. En Estados Unidos, denuncia en ReportFraud.ftc.gov; en otros países, ante la autoridad local pertinente. No garantiza recuperación. Verifica ofertas de recuperar dinero por pago adelantado.')],['Verify identity through independent official contacts.','Check puppy images and claims across separate sources.','Pause for pressure or unexplained extra charges.','Keep evidence and contact the payment provider if concerned.'],['Verifica identidad por contactos oficiales independientes.','Contrasta imágenes y afirmaciones en fuentes separadas.','Para ante presión o cargos inexplicados.','Conserva pruebas y consulta al proveedor de pago.'],[('Does a registration logo prove the seller is legitimate?','No. Verify the specific claim independently with the organization.'),('Will reporting guarantee my money back?','No. Ask your payment provider about applicable options and use official reporting channels.')],[('¿Un logotipo prueba legitimidad?','No. Comprueba la afirmación concreta con la organización.'),('¿Denunciar garantiza recuperar dinero?','No. Consulta opciones al proveedor de pago y utiliza canales oficiales.')])
page(102,('Questions to ask a Doberman breeder—and evidence to request','Use the conversation to understand health screening, puppy raising and written responsibilities. Record evidence beside each answer so a reassuring sales claim does not become an unchecked assumption.'),('Preguntas al criador y evidencia que solicitar','Comprende pruebas de salud, crianza y responsabilidades escritas. Anota evidencia junto a cada respuesta para no convertir una afirmación tranquilizadora en una suposición sin verificar.'),[
('Ask which dogs and records the claims describe','Request registered names or other reliable identifiers for the parents, the test performed, its date and the report. Check available records through the relevant registry or issuing organization. Ask a veterinarian to interpret clinical findings; a health test is not a lifetime guarantee, and a CHIC number does not mean every result was normal.'),('Ask about the actual puppy-raising routine','Discuss how puppies experience people, ordinary household situations, handling and rest. Ask for concrete descriptions rather than a label such as well socialized. Learn how the breeder observes individual behavior and matches homes, and how they support gradual transitions without promising a particular temperament.'),('Read written responsibilities before committing','Request the agreement in advance and clarify identity, payment terms, included records and what happens if care needs or circumstances change. Ask about ongoing support and return arrangements. Have unclear terms explained by an appropriate professional; this guide does not interpret a contract or promise legal protection.'),('A worked evidence note','Example: answer—both parents were screened; evidence needed—parent identifiers, named tests, dates and reports; next action—check the relevant records and discuss interpretation with your veterinarian. Mark missing information as unresolved rather than filling the gap from a testimonial.'),('Make a decision you can explain','Compare the answers with verified evidence, your preparation and the individual puppy’s needs. Club membership and titles may provide context but do not replace checks. Take time to resolve discrepancies, and be willing to pause. Keep the question sheet with your records for the veterinary and home-transition conversations.')],[
('Identifica perros y registros','Solicita nombres registrados u otros identificadores fiables, prueba, fecha e informe de progenitores. Consulta registros disponibles con la entidad correspondiente. Pide interpretación clínica al veterinario: no garantiza salud de por vida, y un número CHIC no significa todos los resultados normales.'),('Pregunta por crianza real','Habla de personas, experiencias domésticas, manejo y descanso. Pide descripciones concretas, no solo bien socializado. Consulta observación individual, elección de hogares y apoyo a transición sin prometer temperamento.'),('Lee responsabilidades antes','Pide acuerdo previo y aclara identidad, pagos, documentación y respuesta ante cambios de cuidados o circunstancias. Pregunta apoyo y devolución. Solicita explicación profesional de cláusulas dudosas; esta guía no interpreta contratos ni promete protección legal.'),('Ejemplo de nota','Respuesta: ambos progenitores examinados. Evidencia: identificadores, pruebas, fechas e informes. Acción: comprobar registros y consultar interpretación veterinaria. Marca datos ausentes como pendientes, sin sustituirlos por testimonios.'),('Decide con razones verificables','Compara respuestas, evidencia y necesidades. Pertenencia y títulos aportan contexto sin sustituir comprobaciones. Resuelve diferencias y permite pausar. Guarda la hoja para conversaciones veterinarias y de adaptación.')],['Request parent identifiers, test names, dates and reports.','Ask for concrete raising and transition practices.','Read the agreement and clarify support responsibilities.','Record evidence received, gaps and next verification steps.'],['Solicita identificadores, pruebas, fechas e informes.','Pregunta prácticas concretas de crianza y transición.','Lee acuerdo y aclara responsabilidades de apoyo.','Anota evidencia, lagunas y próximas comprobaciones.'],[('Does a CHIC number guarantee normal results?','No. Read the available results and discuss their meaning with a veterinarian.'),('Is club membership enough to make a decision?','No. Check the individual breeder’s claims, records, raising practices and written responsibilities.')],[('¿CHIC garantiza resultados normales?','No. Consulta resultados e interpretación veterinaria.'),('¿Basta pertenecer a un club?','No. Verifica afirmaciones, registros, crianza y responsabilidades individuales.')])
page(110,('Build a grooming kit around the task','Start with the care you can perform comfortably and safely, then select suitable tools for a short coat. This is a research-based equipment checklist, not a product ranking or a hands-on durability test.'),('Organiza el kit de higiene según tarea','Empieza por cuidados cómodos y seguros y elige herramientas para pelo corto. Es una lista basada en investigación, no clasificación de productos ni ensayo de duración.'),[
('Separate essentials from treatments','For ordinary coat care, consider a suitable soft brush or grooming mitt, towels and a stable nonslip surface. For bathing, choose a dog product appropriate to the task and follow its label. A medicated product belongs to an individual veterinary plan, not a generic shopping list.'),('Match contact to coat and tolerance','Inspect the working surface of a brush or mitt before use. Begin with a small comfortable area and observe willingness to continue. Stronger scraping or more hair removed is not evidence of better care. Ask a suitable groomer for a demonstration when tool choice is unclear.'),('Prepare nail and dental tools separately','Nail clippers or grinders require safe technique and gradual introduction; owning one does not make a dog ready for trimming. For dental care, ask about an appropriate dog toothbrush and dog toothpaste and comfortable introduction. Consult pain, injury or persistent difficulty rather than buying more tools to force the task.'),('A worked kit comparison','Example only: compare two brushes by their contact surface, suitability for the short coat, cleaning instructions and your dog’s response to a gentle introduction. Record what is documented versus what you observed. No specific brush has been tested for this guide, and a purchase price does not establish suitability.'),('Keep the kit safe between uses','Clean and dry tools as directed, check wear and store them away from chewing or accidental ingestion. Keep products in their original labeled containers. Put professional instructions and your handling notes beside the kit so another caregiver can follow the same plan. Remove damaged tools and pause if handling becomes uncomfortable.')],[
('Separa básicos y tratamientos','Para pelo habitual considera cepillo suave o guante adecuado, toallas y suelo antideslizante. Para baño, producto canino apropiado siguiendo etiqueta. Un producto medicado requiere plan veterinario individual, no lista general.'),('Adapta contacto y tolerancia','Revisa superficie del cepillo o guante. Empieza en zona pequeña cómoda y observa voluntad de continuar. Raspar más o retirar más pelo no demuestra mejores cuidados. Pide demostración profesional ante dudas.'),('Prepara uñas y boca por separado','Cortaúñas y limas necesitan técnica y presentación gradual; tenerlos no significa estar preparado para cortar. Consulta cepillo y pasta canina adecuados e introducción cómoda. Dolor, lesiones o dificultad persistente requieren apoyo, no más herramientas para forzar.'),('Ejemplo de comparación','Compara dos cepillos por superficie, adecuación al pelo corto, limpieza y respuesta a introducción suave. Distingue documentación y observación propia. No hemos probado un cepillo concreto; el precio no demuestra idoneidad.'),('Guarda con seguridad','Limpia y seca según instrucciones, revisa desgaste y guarda lejos de masticación e ingestión. Mantén productos en envases originales. Conserva instrucciones y notas para otros cuidadores. Retira utensilios dañados y para ante incomodidad.')],['List tools by coat, bathing, nail and dental tasks.','Check suitability and product instructions.','Introduce each tool gently and observe tolerance.','Clean, inspect and store safely.'],['Separa pelo, baño, uñas y boca.','Revisa adecuación e instrucciones.','Presenta suavemente y observa tolerancia.','Limpia, revisa y guarda con seguridad.'],[('Do I need every tool immediately?','No. Start with the tasks you can manage safely and seek help or a demonstration for unfamiliar care.'),('Have these products been tested by Doberman Deals?','This guide provides research-based selection criteria and does not claim product testing.')],[('¿Necesito todas las herramientas ya?','No. Empieza por tareas seguras y solicita apoyo para cuidados desconocidos.'),('¿Habéis probado estos productos?','Ofrecemos criterios basados en investigación sin afirmar ensayos de productos.')])
for lang in ('en','es'):
 COPY['DD-110'][lang]['matrix']=[('Coat','Suitable contact surface; observe comfort'),('Bath','Dog product; follow label and skin guidance'),('Nails','Professional technique demonstration when unsure'),('Dental','Dog toothpaste and gradual introduction')] if lang=='en' else [('Pelo','Superficie adecuada y comodidad'),('Baño','Producto canino e instrucciones'),('Uñas','Demostración profesional ante dudas'),('Boca','Pasta canina y presentación gradual')]
